import{_ as i,o as e,c as r,a5 as o,j as t,t as a}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Thiết kế DA-568: Trend Prediction với BM25 Anomaly Detection","description":"","frontmatter":{},"headers":[],"relativePath":"ai-models/DA-568-trend-prediction-bm25-design.md","filePath":"ai-models/DA-568-trend-prediction-bm25-design.md"}'),l={name:"ai-models/DA-568-trend-prediction-bm25-design.md"};function h(c,n,g,u,s,d){return e(),r("div",null,[n[3]||(n[3]=o('<h1 id="thiet-ke-da-568-trend-prediction-voi-bm25-anomaly-detection" tabindex="-1">Thiết kế DA-568: Trend Prediction với BM25 Anomaly Detection <a class="header-anchor" href="#thiet-ke-da-568-trend-prediction-voi-bm25-anomaly-detection" aria-label="Permalink to &quot;Thiết kế DA-568: Trend Prediction với BM25 Anomaly Detection&quot;">​</a></h1><h2 id="_1-luong-xu-ly-nlp-tieng-viet-voi-underthesea" tabindex="-1">1. Luồng xử lý NLP Tiếng Việt với <code>underthesea</code> <a class="header-anchor" href="#_1-luong-xu-ly-nlp-tieng-viet-voi-underthesea" aria-label="Permalink to &quot;1. Luồng xử lý NLP Tiếng Việt với `underthesea`&quot;">​</a></h2><p><strong>Mục tiêu:</strong> Làm sạch dữ liệu văn bản thô (comments, posts) và tách từ (word segmentation) để chuẩn bị cho bước trích xuất đặc trưng.</p><p><strong>Các bước thực hiện:</strong></p><ol><li><strong>Tiền xử lý cơ bản (Basic Preprocessing):</strong><ul><li>Loại bỏ HTML tags, URLs, ký tự đặc biệt, dấu câu và emoji.</li><li>Chuyển đổi toàn bộ văn bản về chữ thường (lowercase).</li><li>Chuẩn hóa Unicode (ví dụ: chuyển từ dạng tổ hợp sang dựng sẵn NFC) để tránh lỗi khi so sánh chuỗi tiếng Việt.</li></ul></li><li><strong>Phân tích cú pháp Tiếng Việt (Word Segmentation):</strong><ul><li>Sử dụng hàm <code>word_tokenize</code> từ thư viện <code>underthesea</code> (tham số <code>format=&quot;text&quot;</code>).</li><li>Ví dụ: <code>&quot;Điện thoại này chụp ảnh đẹp quá&quot;</code> $\\rightarrow$ <code>&quot;Điện_thoại này chụp ảnh đẹp quá&quot;</code>. Việc ghép các âm tiết có nghĩa giúp cải thiện độ chính xác cho việc tính toán TF-IDF và BM25 sau này.</li></ul></li><li><strong>Loại bỏ Stopwords (Stopword Removal):</strong><ul><li>Dùng một danh sách stopword tiếng Việt chuẩn (chứa các từ như: &quot;là&quot;, &quot;và&quot;, &quot;của&quot;, &quot;thì&quot;, &quot;mà&quot;,...) để loại bỏ các từ không mang nhiều giá trị thông tin.</li></ul></li><li><strong>Chuẩn hóa từ vựng (Từ lóng/Viết tắt):</strong><ul><li>Xây dựng từ điển map các từ viết tắt phổ biến trên mạng xã hội (vd: &quot;ko&quot; $\\rightarrow$ &quot;không&quot;, &quot;sp&quot; $\\rightarrow$ &quot;sản phẩm&quot;, &quot;đc&quot; $\\rightarrow$ &quot;được&quot;).</li></ul></li></ol><h2 id="_2-ap-dung-thuat-toan-bm25-anomaly-detection" tabindex="-1">2. Áp dụng thuật toán BM25 Anomaly Detection <a class="header-anchor" href="#_2-ap-dung-thuat-toan-bm25-anomaly-detection" aria-label="Permalink to &quot;2. Áp dụng thuật toán BM25 Anomaly Detection&quot;">​</a></h2><p><strong>Mục tiêu:</strong> Phát hiện sự gia tăng đột biến của các từ khóa (keywords) trong một khoảng thời gian ngắn hiện tại so với dữ liệu lịch sử, từ đó lọc ra top 100 trending keywords.</p><p><strong>Cơ chế hoạt động:</strong></p>',8)),t("ol",null,[n[1]||(n[1]=o("<li><strong>Chia dữ liệu theo Time Windows:</strong><ul><li><strong>Tập Target ($T_{target}$):</strong> Dữ liệu thu thập trong khoảng thời gian hiện tại cần phân tích (ví dụ: 24 giờ qua).</li><li><strong>Tập Background ($T_{background}$):</strong> Dữ liệu thu thập trong quá khứ làm nền tảng tham chiếu (ví dụ: 7 ngày trước đó).</li></ul></li><li><strong>Tính toán Term Frequency (TF) và Inverse Document Frequency (IDF):</strong><ul><li><strong>TF:</strong> Tính tần suất xuất hiện của một từ khóa $q$ trong tập $T_{target}$.</li><li><strong>IDF:</strong> Tính dựa trên mức độ phổ biến của từ khóa trong tập $T_{background}$. Nếu một từ xuất hiện đều đặn trong quá khứ, IDF của nó sẽ thấp (bị phạt). Nếu nó ít xuất hiện trong quá khứ nhưng bùng nổ hiện tại, IDF sẽ cao.</li></ul></li>",2)),t("li",null,[n[0]||(n[0]=t("strong",null,"Tính Anomaly Score theo công thức biến thể của BM25:",-1)),t("ul",null,[t("li",null,"Dựa trên nền tảng của thuật toán Okapi BM25, Anomaly Score được tính toán để ưu tiên các cụm từ (unigram, bigram) có mật độ gia tăng đột biến: $$Score(q) = \\sum \\frac{TF(q, T_{target}) \\cdot (k_1 + 1)}{TF(q, T_{target}) + k_1 \\cdot \\left(1 - b + b \\cdot \\frac{|T_{target}|}{\\text{avg_target_len"+a("}}")+"\\right)} \\times IDF(q, T_{background})$$",1)])]),n[2]||(n[2]=t("li",null,[t("strong",null,"Lọc Top 100 Trending Keywords:"),t("ul",null,[t("li",null,"Đặt ngưỡng tối thiểu cho TF trong $T_{target}$ (ví dụ: phải xuất hiện ít nhất 10 lần) để loại bỏ các từ nhiễu, ít phổ biến."),t("li",null,"Sắp xếp (Rank) tất cả các keywords theo điểm Anomaly Score giảm dần."),t("li",null,"Cắt lấy top 100 từ khóa có điểm số cao nhất làm danh sách trending keywords.")])],-1))]),n[4]||(n[4]=o('<h2 id="_3-tom-tat-kien-truc-pipeline" tabindex="-1">3. Tóm tắt Kiến trúc Pipeline <a class="header-anchor" href="#_3-tom-tat-kien-truc-pipeline" aria-label="Permalink to &quot;3. Tóm tắt Kiến trúc Pipeline&quot;">​</a></h2><ul><li><strong>Nguồn vào:</strong> Dữ liệu raw text từ Social Listening.</li><li><strong>Bước 1 (Clean &amp; NLP):</strong> <code>underthesea</code> (word segmentation), stopword filtering.</li><li><strong>Bước 2 (Feature Extraction):</strong> Tạo N-grams (Unigrams, Bigrams).</li><li><strong>Bước 3 (BM25 Scoring):</strong> Tính điểm Anomaly Score so sánh cửa sổ thời gian (Window-based comparison).</li><li><strong>Đầu ra:</strong> Top 100 từ khóa xu hướng đẩy vào Elasticsearch / CSDL để phục vụ Dashboard hoặc phân tích sâu.</li></ul>',2))])}const T=i(l,[["render",h]]);export{p as __pageData,T as default};
